export const STRINGS = { en: en as Dict, hi };

type ListKey = { [K in StringKey]: (typeof en)[K] extends string[] ? K : never }[StringKey];
type TextKey = Exclude<StringKey, ListKey>;

export function translate(lang: 'en' | 'hi', key: TextKey, vars?: Record<string, string | number>): string {
  // A missing translation shows English (or the key) instead of crashing the screen.
  let s = ((STRINGS[lang][key] ?? STRINGS.en[key] ?? key) as string);
  if (vars) for (const k in vars) s = s.replace('{' + k + '}', String(vars[k]));
  return s;
}

export function translateList(lang: 'en' | 'hi', key: ListKey): string[] {
  return STRINGS[lang][key] as string[];
}

export type { TextKey };

/** BCP-47 locale for speech, voice input and dates. */
export const localeOf = (lang: 'en' | 'hi') => (lang === 'hi' ? 'hi-IN' : 'en-IN');

const FORMATTERS = new Map<string, Intl.DateTimeFormat>();

/** Cached date formatter; building one is slow, so screens reuse them. */
export function dateFormat(lang: 'en' | 'hi', opts: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = lang + JSON.stringify(opts);
  let f = FORMATTERS.get(key);
  if (!f) FORMATTERS.set(key, (f = new Intl.DateTimeFormat(localeOf(lang), opts)));
  return f;
}
